//
// @file emit_test.go
// @brief Tests for what the generator writes out.
//
// The output of a generator is a file somebody compiles, so these tests compile
// it: Go through the parser, C by checking the declarations are ordered and
// guarded, because a generated file that does not compile is a generator
// emitting whatever it likes.
//
// @project Rho
// @version 0.1
// @date 2026
//
// SPDX-License-Identifier: MIT
//

package rhosql

import (
	goparser "go/parser"
	"go/token"
	"strings"
	"testing"
)

// generatedWith runs the generator over the project and returns the four files.
func generatedWith(t *testing.T, results map[string][]ResultColumn) (Result, string, string, string, string) {
	t.Helper()
	result := generated(t, results)
	return result, ModelsGo(result), QueriesGo(result), ModelsC(result), QueriesC(result)
}

func TestTheGeneratedGoIsParseable(t *testing.T) {
	_, models, queries, _, _ := generatedWith(t, nil)
	for name, source := range map[string]string{"models.go": models, "queries.go": queries} {
		if _, err := goparser.ParseFile(token.NewFileSet(), name, source, goparser.ParseComments); err != nil {
			t.Fatalf("the generated %s does not parse: %v\n%s", name, err, source)
		}
	}
}

func TestTheGeneratedGoSaysItIsGenerated(t *testing.T) {
	// A file nobody regenerates is a file nobody trusts, and one nobody
	// overwrites is one that will conflict with a later generation.
	_, models, queries, _, _ := generatedWith(t, nil)
	for name, source := range map[string]string{"models.go": models, "queries.go": queries} {
		if !strings.Contains(source, "Code generated by rho sql. DO NOT EDIT.") {
			t.Errorf("the generated %s does not say it is generated:\n%s", name, source[:120])
		}
	}
}

func TestTheDatabaseHandleIsDeclaredOnce(t *testing.T) {
	// The handle belongs to the statements. Declared in both files it is a
	// redeclaration in every package the generator writes.
	_, models, queries, _, _ := generatedWith(t, nil)
	if strings.Contains(models, "var db *sql.DB") {
		t.Error("the types file declares the database handle as well as the statements")
	}
	if !strings.Contains(queries, "var db *sql.DB") {
		t.Error("the statements file does not declare the database handle")
	}
	// And a types file needs neither of the imports the statements do.
	if strings.Contains(models, "database/sql") {
		t.Error("the types file imports a database it does not use")
	}
}

func TestTheGeneratedCIsGuardedAndOrdered(t *testing.T) {
	_, _, _, models, queries := generatedWith(t, nil)
	for name, source := range map[string]string{"models.h": models, "queries.c": queries} {
		if strings.Count(source, "#ifndef") != 1 {
			t.Errorf("the generated %s does not carry exactly one include guard", name)
		}
		if !strings.Contains(source, "#endif") {
			t.Errorf("the generated %s opens a guard it does not close", name)
		}
	}
	// The statements include the file the types are in, because a struct that
	// holds a string needs the string to have been declared.
	if !strings.Contains(queries, `#include "models.h"`) {
		t.Error("the statements do not include the file the types are in")
	}
}

func TestTheTwoCFilesDoNotShareAGuard(t *testing.T) {
	// Two files of one package with the same guard means whichever is included
	// second is skipped whole, and a translation unit that includes the types and
	// has none of them is a translation unit that does not compile.
	_, _, _, models, queries := generatedWith(t, nil)
	modelsGuard := guardIn(models)
	queriesGuard := guardIn(queries)
	if modelsGuard == "" || queriesGuard == "" {
		t.Fatalf("a file has no guard: %q and %q", modelsGuard, queriesGuard)
	}
	if modelsGuard == queriesGuard {
		t.Errorf("both C files carry the guard %q, so including one skips the other", modelsGuard)
	}
}

// guardIn is the include guard a generated C file carries.
func guardIn(source string) string {
	for _, line := range strings.Split(source, "\n") {
		if strings.HasPrefix(line, "#ifndef ") {
			return strings.TrimSpace(strings.TrimPrefix(line, "#ifndef "))
		}
	}
	return ""
}

func TestTheTwoBackendsSayTheSameThings(t *testing.T) {
	// One reading, two renderings: a statement is a statement in either, and a
	// reader comparing the two files should find the same things in them.
	result, _, goQueries, _, cQueries := generatedWith(t, nil)
	for _, query := range result.Queries {
		if !strings.Contains(goQueries, query.Name) {
			t.Errorf("the generated Go does not mention %s", query.Name)
		}
		if !strings.Contains(cQueries, query.Name) {
			t.Errorf("the generated C does not mention %s", query.Name)
		}
	}
}

func TestAGeneratedStringSurvivesQuotesAndBackslashes(t *testing.T) {
	// A statement is a string literal in both languages, and one with a quote or
	// a backslash in it has to be written so that it is still the statement a
	// service wrote. A generated file that does not compile over a value in the
	// data is a file whose failure points at a line nobody wrote.
	schema := Schema{Queries: []Query{{
		Name: "odd", Verb: VerbSelect, Table: "t",
		SQL:        `SELECT * FROM t WHERE note = 'a "quoted" \ value' AND x = ?`,
		Parameters: []Parameter{{Name: "?", Ordinal: 1, Marker: MarkerPositional}},
	}}}
	result := NewGenerator(schema, "queries", nil).Generate()

	goSource := QueriesGo(result)
	if _, err := goparser.ParseFile(token.NewFileSet(), "queries.go", goSource, 0); err != nil {
		t.Fatalf("a statement with a quote and a backslash does not survive into Go: %v", err)
	}
	cSource := QueriesC(result)
	if !strings.Contains(cSource, `a \"quoted\" \\ value`) {
		t.Errorf("the statement was not escaped in the generated C:\n%s", cSource)
	}
}

func TestAnEmptyProjectGeneratesSomethingThatCompiles(t *testing.T) {
	// A project with no SQL still gets files, and they are files that build: a
	// generated file nobody compiles is a file nobody checks.
	result := NewGenerator(Schema{}, "queries", nil).Generate()
	_, models, queries, _, _ := generatedWith(t, nil)
	_ = result
	for name, source := range map[string]string{"models.go": models, "queries.go": queries} {
		if _, err := goparser.ParseFile(token.NewFileSet(), name, source, 0); err != nil {
			t.Errorf("the generated %s from an empty project does not parse: %v", name, err)
		}
	}
}
